import { Source } from './source';
import { mapEvent } from './mapper';
export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  async *stream(): AsyncGenerator<string> {
    // The body of an async generator starts on the first next() call, so the
    // lease is opened on first iteration only. Calling return()/throw() on a
    // generator that was never iterated never runs this body and therefore
    // neither opens nor closes a lease.
    const lease = await this.source.open();
    // True while an original exception (a failed source read, a failed mapper
    // call, or a consumer-injected throw) is unwinding through this frame.
    // Such an exception has precedence over a failure thrown by close().
    let failing = false;
    try {
      for (;;) {
        // One read per next(): the generator is only resumed when the next()
        // promise is created, and it suspends at the yield below before
        // returning control to the consumer. No read lies ahead of the value
        // being produced, and no read is issued while the consumer processes
        // the previous one.
        let value: string | null;
        try {
          value = await lease.read();
        } catch (error) {
          failing = true;
          throw error;
        }
        if (value === null) break;
        let mapped: string;
        try {
          mapped = this.mapper(value);
        } catch (error) {
          failing = true;
          throw error;
        }
        try {
          yield mapped;
        } catch (error) {
          // A consumer-injected throw surfaces exactly here: the machinery
          // resumes the generator with a throw completion at this yield.
          failing = true;
          throw error;
        }
      }
    } finally {
      // Runs exactly once for the single lease opened above, for every exit
      // path: normal exhaustion, consumer break/return, read failure, mapper
      // failure and consumer-injected throw. If close() itself fails while an
      // original exception is already propagating, the original exception
      // wins; on a clean unwind (exhaustion or break/return) the close
      // failure is propagated instead.
      try {
        await lease.close();
      } catch (closeFailure) {
        if (!failing) throw closeFailure;
      }
    }
  }
}
