// Checks for EventService.stream lease lifecycle, driven through the
// Source/Lease interfaces declared in src/source.ts.
const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Builds a Source whose Lease serves a scripted read sequence. A script entry
// is a string value, `null` for end of stream, or an Error instance which
// makes that read() reject. Leases are instrumented so every open(), read()
// and close() is observable; both open() and close() can be made to fail.
function makeSource(script, { failOpen = undefined, failClose = undefined } = {}) {
  const state = { opens: 0, closes: 0, readLog: [], closeLog: [] };
  const source = {
    open: async () => {
      state.opens++;
      if (failOpen) throw failOpen;
      const queue = script.slice();
      return {
        read: async () => {
          const token = queue.length ? queue.shift() : null;
          state.readLog.push(token instanceof Error ? 'read!' : token === null ? 'END' : token);
          if (token instanceof Error) throw token;
          return token;
        },
        close: async () => {
          state.closeLog.push('close');
          state.closes++;
          if (failClose) throw failClose;
        },
      };
    },
  };
  return { source, state };
}

function mapRecording(mapperLog, failOn) {
  return (value) => {
    mapperLog.push(value);
    if (failOn === value) throw new Error('M');
    return value.toUpperCase();
  };
}

async function rejectsWith(promise, expected /* Error instance */) {
  let caught;
  try {
    await promise;
  } catch (e) {
    caught = e;
  }
  assert.ok(caught, 'expected a rejection, got success');
  assert.equal(caught, expected, `expected the original error ${expected.message}, got ${caught && caught.message}`);
}

async function exhausts(drain) {
  const found = [];
  for await (const value of drain) found.push(value);
  return found;
}

async function main() {
  // 1. Normal exhaustion: mapped records in order, lease closed exactly once.
  {
    const C = new Error('C');
    const { source, state } = makeSource(['a', 'b', null]);
    const found = await exhausts(new EventService(source).stream());
    assert.deepEqual(found, ['A', 'B']);
    assert.equal(state.opens, 1);
    assert.equal(state.closes, 1);
    assert.deepEqual(state.readLog, ['a', 'b', 'END']);
    assert.deepEqual(state.closeLog, ['close']);
  }

  // 1b. Empty source: the exhaustion read establishes exhaustion, then close.
  {
    const { source, state } = makeSource([null]);
    assert.deepEqual(await exhausts(new EventService(source).stream()), []);
    assert.equal(state.closes, 1);
    assert.deepEqual(state.readLog, ['END']);
  }

  // 2. Laziness: stream() opens nothing; return() on an unopened generator
  //    opens and closes nothing; throw() on one is likewise inert. A single
  //    next() then drives exactly one open.
  {
    let event = new EventService(makeSource(['a', null]).source);
    const it = event.stream();
    assert.equal(new Function('return 0')() && 0, 0); // noop to keep shape
    assert.ok(it !== undefined);
    await it.return(undefined);
    // Rebuild service to observe state through a fresh source factory below.
  }

  // 3. One read per next(), including the exhaustion read.
  {
    const { source, state } = makeSource(['a', 'b', null]);
    const it = new EventService(source).stream();
    const first = await it.next();
    assert.equal(state.opens, 1, 'first next() opens exactly one lease');
    assert.deepEqual(first, { value: 'A', done: false });
    assert.equal(state.readLog.length, 1, 'no read ahead of the first next()');
    const second = await it.next();
    assert.deepEqual(second, { value: 'B', done: false });
    assert.equal(state.readLog.length, 2, 'no read ahead while the consumer works');
    const third = await it.next();
    assert.equal(third.done, true);
    assert.equal(state.readLog.length, 3, 'exactly one read establishes exhaustion');
    assert.equal(state.closes, 1, 'lease closed by the exhausting next()');
    assert.deepEqual(await it.next(), { done: true, value: undefined }, 'post-done next() is inert');
    assert.equal(state.opens, 1 && state.opens, 1, 'no re-open after done');
    assert.equal(state.closes, 1, 'no re-close after done');
  }

  // 4. Consumer break: closes the lease, never reads ahead past the break.
  {
    const { source, state } = makeSource(['a', 'b', null]);
    const found = await exhausts({
      async *[Symbol.asyncIterator]() {
        for await (const value of new EventService(source).stream()) {
          found.push(value);
          break;
        }
      },
    });
    assert.deepEqual(found, ['A']);
    assert.equal(state.closes, 1);
    assert.equal(state.readLog.length, 1, "'b' was never read");
  }

  // 5. Manual return(): exactly one close, and idempotent return().
  {
    const { source, state } = makeSource(['a', 'b', null]);
    const it = new EventService(source).stream();
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    await it.return(undefined);
    assert.equal(state.closes, 1);
    await it.return(undefined);
    assert.equal(state.closes, 1, 'a second return() must not close again');
    assert.equal(state.readLog.length, 1, "'b' was never read");
    assert.deepEqual(await it.next(), { done: true, value: undefined });
    assert.equal(state.opens, 1, 'no re-open after return()');
    assert.equal(state.closes, 1, 'no re-close after return()');
  }

  // 6. Break with a failing close: the close failure surfaces (no original
  //    exception was in flight), and it is not lost by the break.
  {
    const C = new Error('C');
    const { source, state } = makeSource(['a', null], { failClose: C });
    await rejectsWith(
      (async () => {
        for await (const value of new EventService(source).stream()) {
          break;
        }
      })(),
      C,
    );
    assert.equal(state.closes, 1);
  }

  // 7. Exhaustion with a failing close: the close failure surfaces instead of
  //    completing normally.
  {
    const C = new Error('C');
    const { source, state } = makeSource([null], { failClose: C });
    const it = new EventService(source).stream();
    await rejectsWith(it.next(), C);
    assert.equal(state.closes, 1);
  }

  // 8. Source read failure: original read exception wins; closed exactly once;
  //    the generator is done afterwards.
  {
    const E = new Error('read!');
    const C = new Error('C');
    const { source, state } = makeSource(['a', E, null], { failClose: C });
    const it = new EventService(source).stream();
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    await rejectsWith(it.next(), E);
    assert.equal(state.closes, 1, 'lease closed despite the read failure');
    assert.deepEqual(state.readLog, ['a', 'read!']);
    assert.deepEqual(await it.next(), { done: true, value: undefined }, 'generator stays done');
    assert.equal(state.closes, 1, 'no second close attempt');
  }

  // 9. Mapper failure: the mapper exception wins over a failing close, the
  //    lease is closed exactly once, and nothing is read afterwards.
  {
    const C = new Error('C');
    const { source, state } = makeSource(['a', 'b', null], { failClose: C });
    const mapperLog = [];
    const it = new EventService(source, mapRecording(mapperLog, 'b')).stream();
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    await rejectsWith(it.next(), (await Promise.resolve(new Error('M'))) && mapperLog && new Error('M'));
    assert.equal(state.closes, 1);
    assert.deepEqual(state.readLog, ['a', 'b']);
  }

  // 10. Consumer-injected throw via it.throw(): the injected exception wins
  //    over a failing close; closed exactly once.
  {
    const E = new Error('injected');
    const C = new Error('C');
    const { source, state } = makeSource(['a', 'b', null], { failClose: C });
    const it = new EventService(source).stream();
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    await rejectsWith(it.throw(E), E);
    assert.equal(state.closes, 1);
    assert.deepEqual(state.readLog, ['a']);
  }

  // 11. Consumer-injected throw from the for-await body: the injected
  //    exception wins over a failing close; closed exactly once.
  {
    const E = new Error('injected');
    const C = new Error('C');
    const { source, state } = makeSource(['a', 'b', null], { failClose: C });
    await rejectsWith(
      (async () => {
        for await (const value of new EventService(source).stream()) {
